#include <vector>
#include <algorithm>

class Solution {
public:
    int minTaps(int n, std::vector<int>& ranges) {
        std::vector<int> maxReach(n + 1, 0);
        for (int i = 0; i <= n; ++i) {
            int left = std::max(0, i - ranges[i]);
            int right = std::min(n, i + ranges[i]);
            maxReach[left] = std::max(maxReach[left], right);
        }
        int taps = 0, curEnd = 0, nextEnd = 0;
        for (int i = 0; i < n; ++i) {
            nextEnd = std::max(nextEnd, maxReach[i]);
            if (i == curEnd) {
                if (nextEnd <= i) return -1;
                curEnd = nextEnd;
                taps++;
            }
        }
        return taps;
    }
};

class Solution {
    public int minTaps(int n, int[] ranges) {
        int[] maxReach = new int[n + 1];
        for (int i = 0; i <= n; i++) {
            int left = Math.max(0, i - ranges[i]);
            int right = Math.min(n, i + ranges[i]);
            maxReach[left] = Math.max(maxReach[left], right);
        }
        int taps = 0, curEnd = 0, nextEnd = 0;
        for (int i = 0; i < n; i++) {
            nextEnd = Math.max(nextEnd, maxReach[i]);
            if (i == curEnd) {
                if (nextEnd <= i) return -1;
                curEnd = nextEnd;
                taps++;
            }
        }
        return taps;
    }
}

var minTaps = function(n, ranges) {
    const maxReach = new Int32Array(n + 1);
    for (let i = 0; i <= n; i++) {
        const left = Math.max(0, i - ranges[i]);
        const right = Math.min(n, i + ranges[i]);
        if (right > maxReach[left]) maxReach[left] = right;
    }
    let taps = 0, curEnd = 0, nextEnd = 0;
    for (let i = 0; i < n; i++) {
        if (maxReach[i] > nextEnd) nextEnd = maxReach[i];
        if (i === curEnd) {
            if (nextEnd <= i) return -1;
            curEnd = nextEnd;
            taps++;
        }
    }
    return taps;
};
